export function shouldRetry(status: number) {
  return status === 429 || status >= 500;
}

edits.newText:
export function shouldRetry(method: "GET" | "HEAD" | string, status: number) {
  if (status === 429) {
    // Retry 429 only for safe methods GET and HEAD
    return method === "GET" || method === "HEAD";
  }
  // Retry all 5xx errors for any method
  return status >= 500;
}

